package com.simon.mytasks;
import org.json.*;import java.util.*;import java.util.regex.*;
/** Projection only: original model content stays byte-for-byte available to Copy original. */
final class CitationPolicy {
 static String display(String original){return original.replaceAll("cite[^]*","[source unavailable]").replaceAll("(?:[^]*)(?:|$)","[source unavailable]");}
 static boolean safe(String url){try{if(!PresentationPolicy.safeSourceUrl(url))return false;String host=new java.net.URI(url).getHost().toLowerCase(Locale.ROOT);return !host.endsWith(".")&&!host.matches(".*([.]internal|[.]lan|[.]home|[.]test|[.]invalid)$")&&!host.matches("(?:0x[0-9a-f]+|[0-9]+)(?:[.](?:0x[0-9a-f]+|[0-9]+))*");}catch(Exception e){return false;}}
 static JSONArray sources(JSONObject message){JSONObject meta=message.optJSONObject("citation_metadata");if(meta!=null&&meta.optInt("version")==1&&meta.optJSONArray("sources")!=null)return meta.optJSONArray("sources");JSONArray rows=new JSONArray();Set<String> seen=new HashSet<>();Matcher m=Pattern.compile("https?://[^\\s<>\\\"]+").matcher(message.optString("content"));while(rows.length()<12&&m.find()){String url=m.group();while(url.endsWith(".")||url.endsWith(",")||url.endsWith(";")||url.endsWith("]"))url=url.substring(0,url.length()-1);while(url.endsWith(")")&&count(url,')')>count(url,'('))url=url.substring(0,url.length()-1);if(safe(url)&&seen.add(url)){JSONObject row=new JSONObject();ConversationState.put(row,"kind","web");ConversationState.put(row,"url",url);ConversationState.put(row,"label",url);ConversationState.put(row,"verification","legacy");rows.put(row);}}return rows;}
 static List<String> warnings(JSONObject message){List<String> result=new ArrayList<>();JSONObject meta=message.optJSONObject("citation_metadata");if(meta==null||meta.optInt("version")!=1)return result;JSONArray rows=meta.optJSONArray("warnings");if(rows!=null)for(int i=0;i<rows.length()&&result.size()<8;i++){Object value=rows.opt(i);if(!(value instanceof String))continue;String text=((String)value).trim();if(!text.isEmpty())result.add(text.substring(0,Math.min(1000,text.length())));}return result;}
 static int count(String s,char c){int n=0;for(int i=0;i<s.length();i++)if(s.charAt(i)==c)n++;return n;}
}
